    string s;
    cin >> s;
    vector<int> beauty(n);
    int sumBeauty = 0;
    for (int i = 0; i < n; i++) {
        cin >> beauty[i];
        sumBeauty += beauty[i];
    }
    int mismatchCount = 0;
    vector<int> freq(26, 0);
    int minPairSum = 0;
    for (int i = 0; i < n / 2; i++) {
        if (s[i] == s[n - i - 1]) {
            mismatchCount++;
            freq[s[i] - 'a']++;
            minPairSum += min(beauty[i], beauty[n - i - 1]);
        }
    }
    int maxFreq = 0;
    int maxCharIdx = 0;
    for (int i = 0; i < 26; i++) {
        if (freq[i] > maxFreq) {
            maxFreq = freq[i];
            maxCharIdx = i;
        }
    }
    if (2 * maxFreq <= mismatchCount) {
        cout << sumBeauty << "\n";
        return 0;
    }
    vector<int> candidates;
